(581031, 60107, 15330, '<td valign="top">I like the colors, the bright yellow, and orange of the fire really stands out from the background. On the other hand this is not very vreative, it seems you just pointed the camera at the fire, and pushed the button. Try to be more creative with this subject next time.</td>', 'I like the colors, the bright yellow, and orange of the fire really stands out from the background. On the other hand this is not very vreative, it seems you just pointed the camera at the fire, and pushed the button. Try to be more creative with this subject next time.', '2004-02-16 00:15:54.000000', NULL, 1),
(581033, 59921, 10848, '<td valign="top">Amazing, love it</td>', 'Amazing, love it', '2004-02-16 00:16:43.000000', NULL, 1),
