(581768, 60255, 14603, '<td valign="top">What a pity this wasn`t in the National Geographic challenge as I`m sure it would have done well.<br/>Good capture.</td>', 'What a pity this wasn`t in the National Geographic challenge as I`m sure it would have done well.Good capture.', '2004-02-16 11:11:39.000000', NULL, 1),
