(586970, 60107, 10848, '<td valign="top">Amazing, this is a great shot, you captured the flames perfectly, the contrast is perfect as well as the colors, great job 9</td>', 'Amazing, this is a great shot, you captured the flames perfectly, the contrast is perfect as well as the colors, great job 9', '2004-02-18 22:37:05.000000', NULL, 1),
