(589560, 59976, 17550, '<td valign="top">Beautiful composition. Minimalist. The colours, the lines, the light fit together in harmony. Great work!</td>', 'Beautiful composition. Minimalist. The colours, the lines, the light fit together in harmony. Great work!', '2004-02-19 23:30:12.000000', NULL, 1),
