(593990, 59876, 6999, '<td valign="top">Profoundly good work Gordon: 12 challenges in and then the 15th hoiighest rated shot on the site - bordering on the unfair :-) Very pleased for you - was going to say keep it up, but perhaps I''d rather the rest of us were left with a chance. Intriguing that all your ''averages'' are whole numbers, too.</td>', 'Profoundly good work Gordon: 12 challenges in and then the 15th hoiighest rated shot on the site - bordering on the unfair :-) Very pleased for you - was going to say keep it up, but perhaps I''d rather the rest of us were left with a chance. Intriguing that all your ''averages'' are whole numbers, too.', '2004-02-23 05:09:56.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(593991, 60505, 6999, '<td valign="top">Congrats Jon - pipped only by a couple of very very good shots. great work - and love the threat in this image.</td>', 'Congrats Jon - pipped only by a couple of very very good shots. great work - and love the threat in this image.', '2004-02-23 05:12:07.000000', NULL, 0),
(593992, 60491, 6999, '<td valign="top">Congrats David.</td>', 'Congrats David.', '2004-02-23 05:14:48.000000', NULL, 0),
(594004, 59876, 14603, '<td valign="top">A big thank you to everyone who voted and commented.<br/> <br/>Quite surprised (but delighted)by the level of success..especially as I was in two minds about submitting this image.<br/>I will post a message later today which will show the original image and the two alternatives that I pondered over.<br/>There have been some enquiries as to how much manipulation went into the shot and my post should confirm that there was very little work needed. I was helped by the perfect conditions and the vantage point which allowed me to crop out the horizon..thus helping create the effect.<br/>Believe me ..it would have to be simple..my prowess at post processing is extremely limited. In fact it would not surprise me if I have done something while downloading this image from my camera which has upset the EXIF....wouldn`t be the first time :-) <br/>Fingers crossed and thanks again to all.<br/> <br/>Gordon</td>', 'A big thank you to everyone who voted and commented. Quite surprised (but delighted)by the level of success..especially as I was in two minds about submitting this image.I will post a message later today which will show the original image and the two alternatives that I pondered over.There have been some enquiries as to how much manipulation went into the shot and my post should confirm that there was very little work needed. I was helped by the perfect conditions and the vantage point which allowed me to crop out the horizon..thus helping create the effect.Believe me ..it would have to be simple..my prowess at post processing is extremely limited. In fact it would not surprise me if I have done something while downloading this image from my camera which has upset the EXIF....wouldn`t be the first time :-) Fingers crossed and thanks again to all. Gordon', '2004-02-23 06:02:35.000000', NULL, 0),
(594006, 59876, 4517, '<td valign="top">Congratulations on your blue ribbon. Your in the "8" club.</td>', 'Congratulations on your blue ribbon. Your in the "8" club.', '2004-02-23 06:12:47.000000', NULL, 0),
(594007, 60491, 4517, '<td valign="top">Another gem from the master.</td>', 'Another gem from the master.', '2004-02-23 06:14:57.000000', NULL, 0),
